#!/usr/bin/env python3
# ticc_binary_capture.py
# Raw serial capture:
# - Waits for the two-line binary header you specified
# - Discards all prior text (banner/config/dots)
# - Prints a "Capture started" line when binary begins
# - Then writes raw bytes verbatim to outfile
# - Periodic status (counts only binary bytes); graceful Ctrl+C and SerialException handling

import argparse
import sys
import time

try:
    import serial  # pyserial
    from serial.serialutil import SerialException
except ImportError:
    print("Missing dependency: pyserial. Install with: pip install pyserial", file=sys.stderr)
    sys.exit(1)


def human_rate(bps: float) -> str:
    if bps >= 1e6:
        return f"{bps/1e6:.2f} MB/s"
    if bps >= 1e3:
        return f"{bps/1e3:.2f} kB/s"
    return f"{bps:.0f} B/s"


def wait_for_binary_header(ser: serial.Serial,show_header) -> None:
    """
    Consume and echo pre-header text until the two-line binary header appears:
      1) "# Binary Timestamp mode - 12 byte frames:"
      2) "# header (0x55,0xAA), channel (1 byte), PICstop (4 bytes), tof (4 bytes), CRC (1 byte)"
    Then return, positioned just after the header.
    """
    want1 = b"# Binary Timestamp mode - 12 byte frames:"
    want2 = (
        b"# header (0x55,0xAA), channel (1 byte), PICstop (4 bytes), "
        b"tof (4 bytes), CRC (1 byte)"
    )
    print("Status: waiting for two-line binary header...", file=sys.stderr)

    buf = bytearray()
    old_timeout = ser.timeout
    ser.timeout = 0.05
    try:
        got1 = False
        while True:
            try:
                chunk = ser.read(1024)
            except SerialException as e:
                print(f"Serial error while reading header: {e}", file=sys.stderr)
                raise SystemExit(2)
            if chunk:
                buf.extend(chunk)
                while True:
                    nl = buf.find(b"\n")
                    if nl < 0:
                        break
                    line = bytes(buf[: nl + 1])  # includes LF
                    del buf[: nl + 1]
                    # Echo line to stderr for visibility
                    if show_header:
                        try:
                            sys.stderr.write(line.decode("utf-8", "replace"))
                        except Exception:
                            sys.stderr.write(repr(line) + "\n")
                    if not got1:
                        if want1 in line:
                            got1 = True
                    else:
                        if want2 in line:
                            print("Status: binary header detected.", file=sys.stderr)
                            return
                        # else keep waiting for the second line
    finally:
        ser.timeout = old_timeout


def capture_raw(ser: serial.Serial, out_f, status_interval: float):
    bytes_total = 0  # counts only binary bytes written
    t0 = time.time()
    t_last = t0

    print("Status: Capture started (binary data now being written).", file=sys.stderr)
    try:
        while True:
            try:
                data = ser.read(8192)
            except SerialException as e:
                print(f"\nSerial error during capture: {e}", file=sys.stderr)
                break
            if data:
                out_f.write(data)
                bytes_total += len(data)

            now = time.time()
            if now - t_last >= status_interval:
                elapsed = max(1e-6, now - t0)
                rate = bytes_total / elapsed
                print(
                    f"Raw: bytes={bytes_total} avg={human_rate(rate)} elapsed={elapsed:.1f}s",
                    file=sys.stderr,
                )
                t_last = now
                out_f.flush()
    except KeyboardInterrupt:
        # Graceful stop
        pass
    finally:
        elapsed = max(1e-6, time.time() - t0)
        rate = bytes_total / elapsed
        print(
            f"\nStopped. Summary: bytes={bytes_total} avg={human_rate(rate)} duration={elapsed:.1f}s",
            file=sys.stderr,
        )


def main():
    p = argparse.ArgumentParser(description="Raw serial capture (header-gated).")
    p.add_argument("--port", required=True)
    p.add_argument("--baud", type=int, required=True)
    p.add_argument("--outfile", required=True)
    p.add_argument("--timeout", type=float, default=0.5)
    p.add_argument("--status-interval", type=float, default=30.0)
    p.add_argument("--show-header", action="store_true")
    args = p.parse_args()

    try:
        ser = serial.Serial(
            port=args.port,
            baudrate=args.baud,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=args.timeout,
        )
        # Avoid auto-reset toggles mid-run if possible
        try:
            ser.dtr = True
            ser.rts = False
        except Exception:
            pass
    except SerialException as e:
        print(f"Failed to open serial port {args.port}: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Failed to open serial port {args.port}: {e}", file=sys.stderr)
        sys.exit(1)

    print(f"Opening {args.port} @ {args.baud} baud. Writing to {args.outfile}", file=sys.stderr)

    try:
        with open(args.outfile, "ab", buffering=0) as f:
            # Wait for two-line binary header (bytes before this are ignored and not counted)
            wait_for_binary_header(ser,show_header=args.show_header)

            # Optional short flush to shed any trailing text bytes still in the driver buffer
            ser.timeout = 0.05
            try:
                _ = ser.read(4096)
            except SerialException as e:
                print(f"Serial error post-header flush: {e}", file=sys.stderr)
                sys.exit(2)

            # Start raw dump (we count and report only these bytes)
            capture_raw(ser, f, status_interval=args.status_interval)
    except KeyboardInterrupt:
        print("\nStopped by user.", file=sys.stderr)
    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == "__main__":
    main()
